CREATE FUNCTION public.florida_county_region(_county text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE WHEN _county=ANY(ARRAY['Escambia','Santa Rosa','Okaloosa','Walton','Holmes','Washington','Bay','Jackson','Calhoun','Gulf','Liberty','Franklin','Gadsden','Leon','Wakulla','Jefferson','Madison','Taylor']) THEN 'panhandle' WHEN _county=ANY(ARRAY['Hamilton','Suwannee','Lafayette','Dixie','Columbia','Baker','Union','Bradford','Nassau','Duval','Clay','St. Johns','Putnam','Flagler']) THEN 'northeast' WHEN _county=ANY(ARRAY['Gilchrist','Alachua','Levy','Marion','Citrus','Hernando']) THEN 'north-central' WHEN _county=ANY(ARRAY['Volusia','Lake','Sumter','Seminole','Orange','Osceola','Brevard','Polk']) THEN 'central' WHEN _county=ANY(ARRAY['Pasco','Pinellas','Hillsborough','Manatee','Sarasota','Hardee','DeSoto','Highlands']) THEN 'tampa-bay' WHEN _county=ANY(ARRAY['Charlotte','Lee','Collier','Glades','Hendry']) THEN 'southwest' WHEN _county=ANY(ARRAY['Indian River','St. Lucie','Okeechobee','Martin','Palm Beach','Broward','Miami-Dade','Monroe']) THEN 'southeast' END $$;
CREATE FUNCTION public.confirm_pilot_geography(_distribution uuid,_county text,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE region text;d public.trip_distributions;BEGIN region:=public.florida_county_region(_county);IF NOT public.has_role(auth.uid(),'admin') OR region IS NULL OR length(trim(_reason)) NOT BETWEEN 5 AND 500 THEN RAISE EXCEPTION 'Master Admin reviewed Florida county and reason required';END IF;SELECT * INTO d FROM public.trip_distributions WHERE id=_distribution FOR UPDATE;IF d.id IS NULL OR d.selected_workspace_id IS NOT NULL OR EXISTS(SELECT 1 FROM public.provider_trip_offers WHERE distribution_id=d.id) THEN RAISE EXCEPTION 'Geography can only be confirmed before offers';END IF;UPDATE public.trip_distributions SET pickup_geography_evidence=jsonb_build_object('state','FL','county',_county,'region',region,'verified',true,'actor',auth.uid(),'at',now(),'source','master_review','reason',trim(_reason)) WHERE id=d.id;PERFORM public.network_audit(d.id,NULL,'pickup_geography_confirmed',jsonb_build_object('county',_county,'region',region,'reason',trim(_reason)));END $$;
DO $change$ DECLARE f text;BEGIN SELECT pg_get_functiondef('public.save_matching_pilot(jsonb,text)'::regprocedure) INTO f;f:=replace(f,'IF EXISTS(SELECT 1 FROM public.platform_launch_flags','IF jsonb_typeof(coalesce(_config->''counties'',''[]''))<>''array'' OR jsonb_typeof(coalesce(_config->''regions'',''[]''))<>''array'' OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(coalesce(_config->''counties'',''[]'')) x WHERE public.florida_county_region(x) IS NULL) OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(coalesce(_config->''regions'',''[]'')) x WHERE x NOT IN (''panhandle'',''northeast'',''north-central'',''central'',''tampa-bay'',''southwest'',''southeast'')) THEN RAISE EXCEPTION ''Invalid Florida geography scope'';END IF; IF EXISTS(SELECT 1 FROM public.platform_launch_flags');f:=replace(f,'jsonb_array_length(_config->''cities'')+jsonb_array_length(_config->''zips'')=0','jsonb_array_length(_config->''cities'')+jsonb_array_length(_config->''zips'')+jsonb_array_length(coalesce(_config->''counties'',''[]''))+jsonb_array_length(coalesce(_config->''regions'',''[]''))=0');EXECUTE f;
SELECT pg_get_functiondef('public.pilot_scope_reason(uuid,uuid)'::regprocedure) INTO f;f:=replace(f,'THEN RETURN ''Authoritative pilot geography required''','AND NOT (d.pickup_geography_evidence->>''state''=''FL'' AND d.pickup_geography_evidence->>''verified''=''true'' AND public.florida_county_region(d.pickup_geography_evidence->>''county'')=d.pickup_geography_evidence->>''region'' AND (coalesce(c->''counties'',''[]'') @> to_jsonb(ARRAY[d.pickup_geography_evidence->>''county'']) OR coalesce(c->''regions'',''[]'') @> to_jsonb(ARRAY[d.pickup_geography_evidence->>''region'']))) THEN RETURN ''Authoritative pilot geography required''');EXECUTE f;
SELECT pg_get_functiondef('public.network_acceptance_candidates(uuid,integer,uuid)'::regprocedure) INTO f;f:=replace(f,'THEN 70 ELSE 20 END','THEN 70 WHEN public.pilot_geography_match(d.id,p.counties,p.matching_settings->>''region'')=''County service-area match'' THEN 40 ELSE 20 END');f:=replace(f,'CASE WHEN distance IS NULL THEN ''[]''::jsonb ELSE jsonb_build_array','CASE WHEN distance IS NULL OR public.pilot_geography_match(d.id,p.counties,p.matching_settings->>''region'')<>'''' THEN ''[]''::jsonb ELSE jsonb_build_array');EXECUTE f;END $change$;
REVOKE ALL ON FUNCTION public.florida_county_region(text),public.confirm_pilot_geography(uuid,text,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.confirm_pilot_geography(uuid,text,text) TO authenticated;